// RE Saison 3 / TypeScript Alpha 2
// HOTFIX16 — single movement decision authority.
// Source TypeScript authoritative; js/movement-authority.js is generated by `npm run build:ts`.
// Operational systems submit GO/CAUTION/STOP constraints here; only this module
// mutates train.blockedBy and publishes the authoritative reason/speed ceiling.
function finiteLimit(value) {
    const n = Number(value);
    return Number.isFinite(n) ? Math.max(0, n) : Infinity;
}
export class MovementAuthority {
    constructor(train) {
        this.train = train || null;
        this.constraints = [];
        this.sequence = 0;
        this.begin();
    }
    begin(baseLimitKmh = Infinity) {
        this.baseLimitKmh = finiteLimit(baseLimitKmh);
        this.constraints.length = 0;
        this.sequence++;
        this._publish();
        return this;
    }
    go() {
        return this.begin(this.baseLimitKmh);
    }
    caution(limitKmh, code = 'CAUTION', reason = 'marche prudente', source = 'runtime', meta = null) {
        const limit = finiteLimit(limitKmh);
        if (!(limit > 0) || limit === Infinity)
            return this;
        this.constraints.push({ status: 'CAUTION', limitKmh: limit, code, reason, source, meta });
        this._publish();
        return this;
    }
    stop(code = 'STOP', reason = 'arrêt de sécurité', source = 'runtime', meta = null) {
        this.constraints.push({ status: 'STOP', limitKmh: 0, code, reason, source, meta });
        this._publish();
        return this;
    }
    limit(limitKmh, code = 'LIMIT', reason = 'restriction de circulation', source = 'runtime', meta = null) {
        const limit = finiteLimit(limitKmh);
        if (limit <= 0)
            return this.stop(code, reason, source, meta);
        return this.caution(limit, code, reason, source, meta);
    }
    _decision() {
        // Per-train/per-step hot path: preserve priority and first-cause ties,
        // without allocating three intermediate filtered arrays on each query.
        let stop = null;
        let caution = null;
        for (const c of this.constraints) {
            if (c.status === 'STOP' || c.limitKmh <= 0) {
                if (!stop || finiteLimit(c.limitKmh) < finiteLimit(stop.limitKmh))
                    stop = c;
            }
            else if (Number.isFinite(c.limitKmh) && c.limitKmh < Infinity) {
                if (!caution || c.limitKmh < caution.limitKmh)
                    caution = c;
            }
        }
        if (stop)
            return { ...stop, status: 'STOP', speedLimitKmh: 0 };
        if (caution)
            return { ...caution, status: 'CAUTION', speedLimitKmh: Math.min(this.baseLimitKmh, caution.limitKmh) };
        return { status: 'GO', speedLimitKmh: this.baseLimitKmh, code: 'GO', reason: '', source: 'movement-authority', meta: null };
    }
    _publish() {
        if (!this.train)
            return;
        const d = this._decision();
        const additionalStop = d.code === 'CAB_CHANGE'
            ? this.constraints.find(c => c.status === 'STOP' && c.code !== 'CAB_CHANGE') : undefined;
        // This is intentionally the single assignment site for blockedBy in HOTFIX16.
        this.train.blockedBy = d.status === 'STOP';
        this.train.movementAuthority = {
            status: d.status,
            code: d.code || d.status,
            reason: d.reason || '',
            source: d.source || 'runtime',
            speedLimitKmh: d.speedLimitKmh,
            sequence: this.sequence,
            ...(additionalStop ? { additionalStop: { code: additionalStop.code, reason: additionalStop.reason } } : {}),
        };
        return d;
    }
    decision() {
        return this._decision();
    }
}
